import sys
sys.setrecursionlimit(10**6)
def comps(g,bg):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                seen.add((i,j))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=y<W and g[x][y]==g[i][j] and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append((g[i][j],sorted(comp)))
    return out
